package com.shopsmart.api;
import com.shopsmart.api.ApiDtos.*;import com.shopsmart.service.AuthService;import jakarta.validation.Valid;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import org.springframework.http.ResponseEntity;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/register") public AuthResponse register(@Valid @RequestBody RegisterRequest r){return auth.register(r);}@PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);}@PostMapping("/logout") @SecurityRequirement(name="bearerAuth") public ResponseEntity<Void> logout(Authentication authentication){auth.logout(authentication.getName());return ResponseEntity.noContent().build();}}
